import {test} from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
const html=fs.readFileSync(new URL('./education_portal_v3_1.html',import.meta.url),'utf8');
function setup(overrides={}){const nodes=new Map();const node=id=>{if(!nodes.has(id))nodes.set(id,{value:'',innerHTML:'',textContent:'',style:{},childNodes:[],scrollTop:0,replaceChildren(...children){this.childNodes=children},querySelector(){return node(id+'_modal')},elements:new Proxy({namedItem:name=>node(id+'_'+name)},{get:(target,key)=>key in target?target[key]:node(id+'_'+String(key))}),classList:{toggle(){},add(){},remove(){}},addEventListener(){},focus(){},isConnected:true});return nodes.get(id)};const storage=new Map();const context={document:{getElementById:node,querySelectorAll:()=>[],addEventListener(){}},localStorage:{getItem:k=>storage.get(k)||null,setItem:(k,v)=>storage.set(k,v)},window:{scrollTo(){}},setTimeout,clearTimeout,setInterval,clearInterval,console,location:{protocol:'file:'},crypto:globalThis.crypto,TextEncoder,TextDecoder,Event,AbortSignal,...overrides};vm.createContext(context);let script=html.match(/<script>([\s\S]*?)<\/script>/)[1];script=script.replace(/\}\)\(\);\s*$/,'globalThis.smsTest={cancelApplications,refreshSmsSelection,renderAdmin,deleteCourseWithApplications,setCourseArchived,editInstructor,pdfPhotoCandidates,showInstructorPhotoCandidates,applyCapturedPhoto,compactStoredImage,compactSaveImages,curriculumInkBounds,render,isPastCourse,renderArchive,showArchivedApplications,storageChanges,safeSave,useSharedState,resizeCourseTextarea,attachCourseAutoGrow,courseEducationContacts,courseContactText,educationContactsMarkup,readEducationContacts,curriculumDownloadName,showCourseMap,fitCurriculumPrintPdf,attachCurriculumFullscreen,configureApplyTest:()=>{storageMode="google-sheets";adminAuthenticated=false},artworkPageIndices,initializeSharedStorage,savePortalState,configureSaveTest:(mode,reauth)=>{storageMode=mode;adminAuthenticated=true;reauthenticateForSave=reauth},validMapData,courseMapUrl,readMapFile,courseGuideModel,wrapGuideText,buildCourseGuidePdf,openCourseGuide,renderCourses,parseProfile,profileParts,packProfileParts,profilePdfCandidates,courseCurriculumMarkup,analyzeCourseMaterial,coursePdfTableLines,selectCoursePages,smsText,validMobile,normalizeMobile,filteredSmsRows,smsSelection,apps,courses,SMS_TEMPLATES,renderStatus,showCourseDetail,showCourseInstructor,outlineMarkup,courseOutlineSummary,summarizeOutlineText,editCourse,instructors,adminAction,openAdminLogin,nav,resetPortalData,openInstructorFromCourse,editInstructorFromCourse,closeModal,refreshCourseInstructor,parseCourseMaterial,applyCourseMaterial,readCourseMaterial,coursePdfLines,getData:()=>({courses,apps,instructors}),getAdminState:()=>adminAuthenticated,setAdminState:value=>{adminAuthenticated=value}};})();');vm.runInContext(script,context);return {api:context.smsTest,node,context}}
test('포털 초기화, 휴대폰 검증과 양식 치환',()=>{const {api,node}=setup();assert(api.validMobile('010-1234-5678'));assert(!api.validMobile('123'));assert(html.includes('id="phone"'));assert(node('statusRows').innerHTML.includes('연락처 수정'));const a=api.apps[0];const result=api.smsText(api.SMS_TEMPLATES.confirm,a,'인사교육팀 / 내선 1234','필기도구');assert(result.includes(a.name));assert(result.includes('생성형 AI'));assert(result.includes('신청상태: 승인'));assert(!/\{[^{}]+\}/.test(result));assert(result.includes('내선 1234'))});
test('전체·선택 대상은 현재 검색과 상태 필터 기준',()=>{const {api,node}=setup();assert.equal(api.filteredSmsRows().length,3);node('statusFilter').value='승인';assert.equal(api.filteredSmsRows().length,1);node('statusFilter').value='';node('statusSearch').value='김예시';assert.equal(api.filteredSmsRows().length,1);api.smsSelection.add('a1');assert.equal(api.filteredSmsRows().filter(a=>api.smsSelection.has(a.id)).length,0);api.smsSelection.add('a2');assert.equal(api.filteredSmsRows().filter(a=>api.smsSelection.has(a.id)).length,1)});

test('교육과정 콤보 전체 목록과 과정별 신청내역·문자 대상 연동',()=>{const {api,node}=setup();for(const c of api.courses)assert(node('statusCourseFilter').innerHTML.includes('value="'+c.id+'"'));assert(node('statusCourseFilter').innerHTML.includes('신청 0건'));node('statusCourseFilter').value='c1';api.renderStatus();assert.equal(api.filteredSmsRows().length,2);assert(!node('statusRows').innerHTML.includes('김예시'));node('statusFilter').value='승인';assert.equal(api.filteredSmsRows().length,1);node('statusFilter').value='';node('statusCourseFilter').value='c6';api.renderStatus();assert.equal(api.filteredSmsRows().length,0);assert(node('statusRows').innerHTML.includes('신청 내역이 없습니다'));node('statusCourseFilter').value='';api.renderStatus();assert.equal(api.filteredSmsRows().length,3)});

test('과정 상세·강사 프로필·등록항목·A4 개요서 연결',()=>{const {api,node}=setup();const c=api.courses[0];c.target='전체 임직원';c.objectives='현업 적용 역량 강화';c.curriculum='09:00 개념 학습\n10:00 실습';c.materials='노트북';c.notices='10분 전 입실';c.instructorId='teacher-test';api.instructors.push({id:'teacher-test',name:'홍강사',company:'미래연구소',education:'경영학 석사',career:'교육 담당',history:'리더십',books:'학습의 힘'});api.showCourseDetail(c.id);let detail=node('modalRoot').innerHTML;for(const text of ['강사 프로필','교육 안내문 출력','현업 적용 역량 강화','09:00 개념 학습','10분 전 입실'])assert(detail.includes(text));api.showCourseInstructor(c.id);assert(node('modalRoot').innerHTML.includes('경영학 석사'));assert(node('modalRoot').innerHTML.includes('과정 상세로 돌아가기'));api.editCourse(c.id);for(const field of ['target','objectives','curriculum','materials','notices'])assert(node('modalRoot').innerHTML.includes('name="'+field+'"'));const print=api.outlineMarkup(c);for(const value of ['size:A4 portrait','height:272mm','학습목표','세부내용 (커리큘럼)','교육일정','교육시간','교육장소','모집정원','담당강사명','준비물 및 안내사항','홍강사','노트북','10분 전 입실','흥국금융그룹 HRD 문의 : 02-2002-6803 김명배 차장, 02-2002-7223 강석대 과장 / 서울 종로구 새문안로 68 흥국생명빌딩'])assert(print.includes(value),value);c.notices='<script>malicious</script>';assert(!api.outlineMarkup(c).includes('<script>malicious</script>'));assert(api.outlineMarkup(c).includes('&lt;script&gt;'))});

test('좌측 일반 메뉴에서 관리자 전용 메뉴 제거 및 내부 탭 구성',()=>{assert(!html.includes('data-page="status"'));assert(!html.includes('data-page="instructors"'));for(const label of ['data-admin-tab="status"','data-admin-tab="instructors"','비밀번호 변경','로그아웃'])assert(html.includes(label));const {api}=setup();assert.equal(api.getAdminState(),false)});
test('독립 HTML 비밀번호 설정·로그인·변경 검증',async()=>{const {api}=setup();assert.equal((await api.adminAction('status')).initialized,false);await api.adminAction('setup',{password:'first-password'});await assert.rejects(api.adminAction('login',{password:'incorrect'}));assert.equal((await api.adminAction('login',{password:'first-password'})).authenticated,true);api.setAdminState(true);await api.adminAction('change',{currentPassword:'first-password',password:'second-password'});await assert.rejects(api.adminAction('login',{password:'first-password'}));assert.equal((await api.adminAction('login',{password:'second-password'})).authenticated,true);await api.adminAction('logout');assert.equal(api.getAdminState(),false)});

test('HTTPS 정적 미리보기에서 인증 API가 없으면 로그인 화면과 관리자 진입 정상 동작',async()=>{const {api,node}=setup({location:{protocol:'https:',hostname:'preview.example'},fetch:async()=>new Response('<html>Static preview</html>',{status:200,headers:{'Content-Type':'text/html'}})});await api.openAdminLogin();assert(node('modalRoot').innerHTML.includes('관리자 비밀번호 최초 설정'));node('adminPassword').value='preview-password';node('adminPasswordConfirm').value='preview-password';await node('adminLoginForm').onsubmit({preventDefault(){}});assert.equal(api.getAdminState(),true);assert.equal(node('pagetitle').textContent,'관리자 관리')});
test('blob HTML 미리보기는 인증 서버 요청 없이 비밀번호 설정 화면 열기',async()=>{const {api,node}=setup({location:{protocol:'blob:'},fetch:()=>{throw Error('should not fetch')}});await api.openAdminLogin();assert(node('modalRoot').innerHTML.includes('관리자 비밀번호 최초 설정'))});
test('서버 오류는 로컬 인증으로 우회하지 않음',async()=>{const {api}=setup({location:{protocol:'https:',hostname:'portal.example'},fetch:async()=>new Response(JSON.stringify({error:'서버 장애'}),{status:503,headers:{'Content-Type':'application/json'}})});await assert.rejects(api.adminAction('status'),/서버 장애/)});

test('신청내역 리셋은 두 번 경고하고 교육과정·강사자료를 보존',async()=>{let asked=0;const {api}=setup({confirm:()=>{asked++;return true},alert:()=>{throw Error('unexpected alert')}});api.setAdminState(true);const before=api.getData(),courses=JSON.stringify(before.courses),instructors=JSON.stringify(before.instructors);api.smsSelection.add('a1');assert.equal(await api.resetPortalData(),true);assert.equal(asked,2);const data=api.getData();assert.equal(JSON.stringify(data.courses),courses);assert.equal(data.apps.length,0);assert.equal(JSON.stringify(data.instructors),instructors);assert.equal(api.smsSelection.size,0);assert.equal(api.getAdminState(),true);assert(html.indexOf('id="resetPortalData"')>html.indexOf('id="statusView"'));assert(html.indexOf('id="resetPortalData"')<html.indexOf('id="archiveView"'))});
test('데이터 리셋 취소 시 데이터 유지',async()=>{const {api}=setup({confirm:()=>false});api.setAdminState(true);await api.resetPortalData();assert.equal(api.getData().courses.length,6);assert.equal(api.getData().apps.length,3)});

test('교육자료 유사 제목 및 분리된 항목명을 6개 입력란으로 분류',()=>{const {api}=setup();const text='1. 과정 개요: 생성형 AI 실무\n2. 수강 대상\n영업지원 담당자\n3. 기대 효과: 보고서 작성 역량 강화\n4. 교육 프로그램\n09:00 개념 이해\n10:00 실습\n5. 사전 준비사항: 노트북 지참\n6. 유의 사항\n10분 전 입실\n문의처: 교육팀';const r=api.parseCourseMaterial(text);assert.equal(r.description,'생성형 AI 실무');assert.equal(r.target,'영업지원 담당자');assert.equal(r.objectives,'보고서 작성 역량 강화');assert(r.curriculum.includes('10:00 실습'));assert.equal(r.materials,'노트북 지참');assert.equal(r.notices,'10분 전 입실');const spaced=api.parseCourseMaterial('[학 습 목 표]\n실무 활용\n교육 대상: 임직원');assert.equal(spaced.objectives,'실무 활용');assert.equal(spaced.target,'임직원')});
test('교육자료 영문 제목 및 기존 입력 유지·덮어쓰기·길이 초과 표시',()=>{const {api}=setup();const raw='Overview: AI\nTarget audience: 직원\nLearning objectives: 업무 개선\nCurriculum: 실습\nMaterials: 노트북\nImportant information: 지각 금지';const r=api.parseCourseMaterial(raw);assert.equal(Object.keys(r).length,6);const fields={};for(const k of Object.keys(r))fields[k]={value:k==='description'?'기존 소개':'',maxLength:k==='materials'?2:1000,dispatchEvent(){}};let result=api.applyCourseMaterial(raw,{elements:{namedItem:k=>fields[k]}},false);assert.equal(fields.description.value,'기존 소개');assert.equal(result.kept.length,1);assert.equal(result.trimmed.length,1);result=api.applyCourseMaterial(raw,{elements:{namedItem:k=>fields[k]}},true);assert.equal(fields.description.value,'AI');assert.equal(result.filled.length,6)});
test('텍스트 자료 읽기 및 파일 크기·구형 형식 오류 안내',async()=>{const {api}=setup();const content='교육 대상: 임직원';const file={name:'course.txt',size:100,arrayBuffer:async()=>new TextEncoder().encode(content).buffer};assert.equal((await api.readCourseMaterial(file)).text,content);await assert.rejects(api.readCourseMaterial({...file,size:21*1024*1024}),/20MB/);await assert.rejects(api.readCourseMaterial({...file,name:'course.hwp'}),/PDF/)});
test('PDF 텍스트는 화면 행 순서로 복원하고 버튼은 고대비 카드로 표시',()=>{const {api,node}=setup();const lines=api.coursePdfLines([{str:'대상: 임직원',height:10,transform:[1,0,0,1,30,100]},{str:'교육',height:10,transform:[1,0,0,1,10,100]},{str:'학습목표: 실무',height:10,transform:[1,0,0,1,10,80]}]);assert.equal(lines[0],'교육 대상: 임직원');assert.equal(lines[1],'학습목표: 실무');api.showCourseDetail('c1');assert(node('modalRoot').innerHTML.includes('class="course-detail-action"'));assert(node('modalRoot').innerHTML.includes('class="course-detail-action print"'));api.editCourse('c1');assert(node('modalRoot').innerHTML.includes('PDF·이미지 파일 선택'));assert(!node('modalRoot').innerHTML.includes('courseImportOverwrite'))});

test('과정개요서에 담당강사 이름·소속·사진을 포함하며 사진 미등록 안내 지원',()=>{const {api}=setup();const c=api.courses[0];c.instructorId='portrait-teacher';api.instructors.push({id:'portrait-teacher',name:'사진강사',company:'교육연구소',position:'대표',specialty:'리더십',photo:'data:image/png;base64,TESTPHOTO'});const out=api.outlineMarkup(c);assert(out.includes('alt="사진강사 강사 사진"'));assert(out.includes('data:image/png;base64,TESTPHOTO'));assert(out.includes('사진강사'));assert(out.includes('교육연구소'));assert(out.includes('height:272mm'));api.instructors[0].photo='';assert(api.outlineMarkup(c).includes('사진 미등록'))});
test('과정에서 강사 등록 취소 시 입력한 과정 내용 유지',()=>{const {api,node}=setup();api.setAdminState(true);api.editCourse();node('courseForm_title').value='작성 중인 교육과정';node('courseForm_curriculum').value='진행 중인 커리큘럼';api.openInstructorFromCourse();assert(node('modalRoot').innerHTML.includes('신규 강사 등록'));api.closeModal();assert.equal(node('courseForm_title').value,'작성 중인 교육과정');assert.equal(node('courseForm_curriculum').value,'진행 중인 커리큘럼')});
test('과정에서 강사 신규 등록 저장 후 자동 선택',async()=>{const data={name:'새강사',company:'태광연구소',position:'대표',birthYear:'',education:'교육학 석사',career:'교육담당',history:'리더십',books:'',specialty:'리더십',contact:''};class FakeFormData{get(key){return data[key]??''}}const {api,node}=setup({FormData:FakeFormData});api.setAdminState(true);api.editCourse();node('courseForm_title').value='작성중';api.openInstructorFromCourse();await node('instructorForm').onsubmit({preventDefault(){},target:{dataset:{}}});assert.equal(api.getData().instructors.length,1);assert.equal(node('courseForm_instructorId').value,api.getData().instructors[0].id);assert(node('courseInstructorSummary').textContent.includes('새강사'));assert.equal(node('courseForm_title').value,'작성중')});

test('과정개요서는 원문을 유지하며 1페이지용 핵심 요약·필수 안내 우선 추출',()=>{const {api}=setup();const c=api.courses[0];c.curriculum=Array.from({length:30},(_,i)=>'모듈 '+i+' 생성형 AI 업무 활용 사례와 실습 상세내용을 학습합니다.').join('\n');c.notices='일반 참고 설명\n다른 참고 설명\n추가 참고 설명\n노트북 반드시 지참\n안전수칙 필수 준수';const original=c.curriculum;const summary=api.courseOutlineSummary(c);assert(summary.curriculum.text.length<=450);assert(summary.curriculum.text.split('\n').length<=6);assert(summary.notices.text.includes('반드시'));assert(summary.notices.text.includes('안전수칙'));const out=api.outlineMarkup(c);assert(out.includes('핵심 요약본'));assert(out.includes('height:272mm'));assert.equal(c.curriculum,original)});

test('관리자 메뉴 연속 클릭은 입력한 비밀번호와 폼을 유지',async()=>{const {api,node}=setup();await api.openAdminLogin();const markup=node('modalRoot').innerHTML;node('adminPassword').value='입력중';await api.openAdminLogin();assert.equal(node('modalRoot').innerHTML,markup);assert.equal(node('adminPassword').value,'입력중');node('modalBack').onclick({target:node('modalBack')});assert.equal(node('modalRoot').innerHTML,markup);node('closeModal').onclick();assert.equal(node('modalRoot').innerHTML,'');await api.openAdminLogin();assert(node('modalRoot').innerHTML.includes('adminLoginForm'))});
test('관리자 인증 확인 중 중복 클릭을 합치고 취소 뒤 늦은 응답은 무시',async()=>{let release,calls=0;const gate=new Promise(resolve=>release=resolve);const {api,node}=setup({location:{protocol:'https:',hostname:'example.com'},fetch:async url=>{if(url==='/api/data/status')return {ok:true,json:async()=>({configured:false})};calls++;await gate;return {ok:true,headers:{get:()=> 'application/json'},json:async()=>({initialized:true,authenticated:false})}}});const pending=api.openAdminLogin();await api.openAdminLogin();assert.equal(calls,1);api.closeModal();release();await pending;assert.equal(node('modalRoot').innerHTML,'')});
test('틀린 관리자 비밀번호는 창을 닫지 않고 오류 표시 후 재입력 허용',async()=>{const {api,node}=setup({location:{protocol:'https:',hostname:'example.com'},fetch:async url=>({ok:!url.endsWith('/login'),headers:{get:()=> 'application/json'},json:async()=>url.endsWith('/login')?{error:'비밀번호가 일치하지 않습니다.'}:{initialized:true,authenticated:false}})});await api.openAdminLogin();node('adminPassword').value='wrong';await node('adminLoginForm').onsubmit({preventDefault(){}});assert(node('modalRoot').innerHTML.includes('adminLoginForm'));assert(node('adminLoginError').textContent.includes('일치하지'));assert.equal(node('adminLoginSubmit').disabled,false);assert.equal(api.getAdminState(),false)});

test('관리자 비밀번호 변경 버튼과 바깥 클릭으로 닫히지 않는 변경창',()=>{const {api,node}=setup();api.setAdminState(true);node('changeAdminPassword').onclick();assert(node('modalRoot').innerHTML.includes('현재 비밀번호'));assert(node('modalRoot').innerHTML.includes('새 비밀번호 확인'));const markup=node('modalRoot').innerHTML;node('modalBack').onclick({target:node('modalBack')});assert.equal(node('modalRoot').innerHTML,markup)});


test('과정내용·과정목적 유사어와 기본정보를 각각 분류',()=>{const {api}=setup();const r=api.parseCourseMaterial('교육명: 상담 실무과정\n과정 목적: 상담 역량 향상\n대상: 상담 담당자 24명\n일정: 2026년 11월 6일 09:00~13:00\n장소: 본사 대회의실\n과정내용: 고객 심리 분석\n지참물: 노트북');assert.equal(r.title,'상담 실무과정');assert.equal(r.objectives,'상담 역량 향상');assert.equal(r.curriculum,'고객 심리 분석');assert.equal(r.capacity,'24');assert.equal(r.date,'2026-11-06');assert.equal(r.endDate,'2026-11-06');assert.equal(r.startTime,'09:00');assert.equal(r.place,'본사 대회의실');assert.equal(r.materials,'노트북')});
test('명시적인 제목이 다음 줄에 있어도 성명·강의주제로 덮어쓰지 않음',()=>{const {api}=setup();const r=api.parseCourseMaterial('교육명:\n생성형 AI 활용\n강사명:\n가상강사\n성명 가상강사 소속 연구소\n강의 주제:\n엑셀 실습\n학습목표: 업무 효율 향상');assert.equal(r.title,'생성형 AI 활용');assert.equal(r.objectives,'업무 효율 향상')});
test('미분류 본문은 커리큘럼에 넣지 않고 별도 보관',()=>{const {api}=setup();const r=api.analyzeCourseMaterial('이 자료는 항목명이 없는 일반적인 참고 문장입니다.');assert.equal(r.fields.curriculum,undefined);assert.equal(r.unmatched.length,1);assert(r.warnings.length)});
test('여러 차수·장기간·불명확한 정원은 임의로 확정하지 않음',()=>{const {api}=setup();for(const text of ['교육기간: 2026.7.13 ~ 8.14 총 7회 진행','일정: 1차 [2026.9.11~12] / 2차 [2026.9.15~16]','교육일시: 미정']){const r=api.analyzeCourseMaterial(text);assert.equal(r.fields.date,undefined);assert(r.warnings.length)}assert.equal(api.parseCourseMaterial('교육인원: 프로그램별 25~35명').capacity,undefined);assert.equal(api.parseCourseMaterial('교육인원: 25명 미만').capacity,undefined)});
test('문서에 적힌 연도와 연속 2일 일정을 함께 인식',()=>{const {api}=setup();const r=api.parseCourseMaterial('2026년 경력입사자 입문과정\n기간: 11월 9일 ~ 11월 10일\n대상: 경력직 입사자41명');assert.equal(r.date,'2026-11-09');assert.equal(r.endDate,'2026-11-10');assert.equal(r.capacity,'41')});
test('표 제목 행에서 주요내용을 찾아 학습목표와 커리큘럼 분리',()=>{const {api}=setup();const r=api.parseCourseMaterial('교육목표: 데이터 분석 역량 강화\n주제\t주요내용\t시간\t교수법\n실무 데이터 분석 실습');assert.equal(r.objectives,'데이터 분석 역량 강화');assert.equal(r.curriculum,'실무 데이터 분석 실습')});
test('표에서 수직 중앙에 놓인 학습목표 제목을 본문 앞으로 복원',()=>{const {api}=setup();const item=(str,x,y)=>({str,width:50,height:10,transform:[1,0,0,1,x,y]});const lines=api.coursePdfTableLines([item('학습목표',50,150),item('첫째 목표',200,175),item('둘째 목표',200,125),item('교육명',50,250),item('실무 과정',200,250)],[300,200,100],600);const r=api.parseCourseMaterial(lines.join('\n'));assert.equal(r.title,'실무 과정');assert(r.objectives.includes('첫째 목표'));assert(r.objectives.includes('둘째 목표'))});
test('페이지 선택은 입력 범위만 순서대로 분석하고 범위 오류 차단',()=>{const {api}=setup();const pages=['표지','과정 A','과정 B','강사'];assert.equal(api.selectCoursePages(pages,'2,3-3')[0].text,'과정 A');assert.equal(api.selectCoursePages(pages,'2,3-3').length,2);assert.throws(()=>api.selectCoursePages(pages,'0'));assert.throws(()=>api.selectCoursePages(pages,'2-9'));assert.throws(()=>api.selectCoursePages(pages,'x'))});
test('교육계획 본문과 별첨 강사 개인정보는 분리',()=>{const {api}=setup();const r=api.parseCourseMaterial('[문서 1]\n교육목표: 협업 역량 강화\n과정내용: 협업 실습\n[문서 2]\n별첨 강사 프로필\n학력: 가상대학교\n연락처: 비공개\n[문서 3]\n교육목표: 새로운 과정 목표');assert(!JSON.stringify(r).includes('가상대학교'));assert(!JSON.stringify(r).includes('비공개'));assert(r.objectives.includes('새로운 과정 목표'))});
test('과정 자동 채우기 패널 제거 및 세부내용 원본 첨부 유지',()=>{const {api,node}=setup();api.editCourse();const markup=node('modalRoot').innerHTML;assert(!markup.includes('courseImportPreview'));assert(!markup.includes('확인한 항목 적용'));assert(!markup.includes('coursePageRange'));assert(markup.includes('세부내용 첨부하기(PDF/캡처가능)'))});


test('강사 프로필은 소속·학력·자격·출강처·연구저술을 구분',()=>{const {api}=setup();const r=api.parseProfile('성명: 홍길동\n직장명: 교육연구소\n직위: 대표\n학력 및 경력사항\n가상대학교 교육학 석사\n전) 기업교육팀장\n자격사항\n평생교육사 2급\n강의분야\n리더십, 코칭\n주요출강처\n가상생명, 가상화재\n연구저술\n학습 전이 연구\n방송활동\n교육 방송 출연');assert.equal(r.name,'홍길동');assert.equal(r.company,'교육연구소');assert(r.education.includes('석사'));assert(!r.education.includes('교육사'));assert(r.career.includes('평생교육사'));assert.equal(r.specialty,'리더십, 코칭');assert.equal(r.clients,'가상생명, 가상화재');assert.equal(r.research,'학습 전이 연구');assert.equal(r.activities,'교육 방송 출연')});
test('프로필의 주소·계좌·주민번호는 등록 항목에 넣지 않음',()=>{const {api}=setup();const r=api.parseProfile('성명: 홍길동\n주소: 비공개 주소\n은행 및 계좌번호\n999-1234-5555\n주민등록번호: 비공개 번호\n강의분야: 코칭');assert(!JSON.stringify(r).includes('비공개'));assert(!JSON.stringify(r).includes('999'));assert.equal(r.specialty,'코칭')});
test('추가 항목은 기존 시트 저장·공개조회 필드로 보존하고 다시 분리',()=>{const {api}=setup();const x={history:'성과코칭',clients:'가상회사',books:'코칭 입문',research:'현장 연구',career:'HRD 팀장',activities:'교육 방송',contact:'01012345678',email:'trainer@example.test'};const packed=api.packProfileParts(x);const oldProjection={history:packed.history,books:packed.books,career:packed.career,contact:packed.contact};const decoded=api.profileParts(oldProjection);for(const key of Object.keys(x))assert.equal(decoded[key],x[key],key);assert.equal(api.profileParts({history:'기존 강의이력',books:'기존 저서'}).history,'기존 강의이력')});
test('표의 성명·생년월일·직장명·직위를 탭으로 분리',()=>{const {api}=setup();const r=api.parseProfile('성명\t홍길동\t생년월일\t1980.01.02\n직장명\t교육연구소\t직위\t대표');assert.equal(r.name,'홍길동');assert.equal(r.birthYear,'1980');assert.equal(r.company,'교육연구소');assert.equal(r.position,'대표')});
test('강사 등록 화면은 전문분야·출강처·이메일·추가정보를 분리',()=>{const {api,node}=setup();api.setAdminState(true);api.openInstructorFromCourse();const html=node('modalRoot').innerHTML;assert(html.includes('name="clients"'));assert(html.includes('name="email"'));assert(html.includes('name="research"'));assert(html.includes('profileCandidateControls'));assert(!html.includes('name="address"'));assert(!html.includes('name="bank"'))});
test('커리큘럼 모듈은 원문에 있는 일차·모듈만 표시하고 HTML 이스케이프',()=>{const {api}=setup();const out=api.courseCurriculumMarkup('1일차\nAI 개념 학습\n2일차\n실습 <script>');assert(out.includes('1일차'));assert(out.includes('2일차'));assert(out.includes('&lt;script&gt;'));assert(!out.includes('7시간'))});
test('과정 상세는 핵심정보 요약과 대상·목표·커리큘럼 바로가기 제공',()=>{const {api,node}=setup();api.showCourseDetail('c1');const out=node('modalRoot').innerHTML;assert(out.includes('course-summary-grid'));assert(!out.includes('data-course-section="audience"'));assert(out.includes('education-contact-cards'));assert(out.includes('courseSection-contents'));assert(out.includes('course-detail-footer'))});

test('프로필 표의 경력 머리글과 현직 글자 간격을 처리',()=>{const {api}=setup();const r=api.parseProfile('성명\t홍길동\n현\t직 : 가상대학교 경영학과 교수\n[경력 사항]\n기간\t회사명\t부서\t직위\t비고\n2013~2015\t가상회사\t교육팀\t전문강사');assert.equal(r.company,'가상대학교 경영학과');assert.equal(r.position,'교수');assert(r.career.includes('2013~2015'));assert(r.career.includes('가상회사'));assert(!r.career.includes('회사명'))});


test('교육안내문은 목록·상세에서 열고 디자인만 선택',()=>{const {api,node}=setup();api.renderCourses();assert(node('courseGrid').innerHTML.includes('교육 안내문 출력'));api.showCourseDetail('c1');assert(node('modalRoot').innerHTML.includes('교육 안내문 출력'));api.editCourse('c1');assert(node('modalRoot').innerHTML.includes('name="guideTheme"'));assert(node('modalRoot').innerHTML.includes('필수교육 · 딥그린'));assert(!node('modalRoot').innerHTML.includes('name="guideIntro"'));assert(!node('modalRoot').innerHTML.includes('name="guideGoals"'));assert(!node('modalRoot').innerHTML.includes('name="guideCurriculum"'))});
test('안내문 요약은 원문과 분리하고 준비물·주의사항은 모두 유지',()=>{const {api}=setup();const c={...api.courses[0],description:'상세한 원문 소개',objectives:'상세 목표',curriculum:'전체 커리큘럼',materials:'필수 계정 준비\n노트북 지참',notices:'사전 설치 필수\n일정 변경 안내',guide:{intro:'검토한 소개',goals:'검토한 목표',curriculum:'검토한 요약'}};const m=api.courseGuideModel(c,null);assert.equal(m.intro,c.description);assert.equal(m.goals,c.objectives);assert.equal(m.curriculum,c.curriculum);assert.equal(m.materials,c.materials);assert.equal(m.notices,c.notices);assert.equal(c.curriculum,'전체 커리큘럼');assert.equal(m.place,c.place)});
test('한글과 공백없는 긴 문장도 고정 글자 크기에서 줄바꿈',()=>{const {api}=setup();const font={widthOfTextAtSize:(text,size)=>Array.from(text).length*size};const text='한글문장과긴영문ABCDEF'.repeat(10);const lines=api.wrapGuideText(text,font,10,100);assert(lines.length>1);assert.equal(lines.join(''),text);for(const line of lines)assert(font.widthOfTextAtSize(line,10)<=100)});
test('PDF 생성은 A4 최소2쪽·페이지 추가·연락처 유지·본문 자르기 없음',async()=>{const {api}=setup();const documents=[];const PDFLib={rgb:(...values)=>values,PDFDocument:{create:async()=>{const pages=[];const doc={registerFontkit(){},embedFont:async()=>({getCharacterSet:()=>Array.from({length:65536},(_,i)=>i),widthOfTextAtSize:(text,size)=>Array.from(text).length*size*.55}),addPage:dimensions=>{const page={dimensions,drawText(){},drawRectangle(){},drawLine(){}};pages.push(page);return page},getPageCount:()=>pages.length,getPages:()=>pages,setTitle(){},setAuthor(){},setSubject(){},setLanguage(){},setCreationDate(){},save:async()=>new Uint8Array([37,80,68,70])};documents.push(doc);return doc}}};const resources={PDFLib,fontkit:{},fontBytes:new Uint8Array([1])};const short={...api.courses[0],description:'과정 소개',objectives:'실무 역량 강화',curriculum:'1일차\n개념 학습\n2일차\n현업 실습'};const result=await api.buildCourseGuidePdf(short,null,resources);assert.equal(result.pageCount,2);const long={...short,curriculum:Array.from({length:160},(_,i)=>'모듈 본문 '+i+' 핵심 내용을 빠짐없이 제공합니다.').join('\n'),materials:'필수 준비물 전체 문장',notices:'주의사항 전체 문장'};const expanded=await api.buildCourseGuidePdf(long,null,resources);assert(expanded.pageCount>2);assert(expanded.drawn.some(x=>x.text.includes('모듈 본문 159')));assert(expanded.drawn.some(x=>x.text.includes(long.materials)));assert(expanded.drawn.some(x=>x.text.includes(long.notices)));for(const line of expanded.drawn)assert(line.y>=30&&line.y<842)});

test('실제 PDF 라이브러리와 한글 글꼴로 PDF를 생성·재열기', {timeout:90000},async()=>{
 const urls=['https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js','https://cdn.jsdelivr.net/npm/@pdf-lib/fontkit@1.1.1/dist/fontkit.umd.min.js','https://cdn.jsdelivr.net/gh/google/fonts@main/ofl/nanumgothic/NanumGothic-Regular.ttf'];
 const responses=await Promise.all(urls.map(url=>fetch(url,{signal:AbortSignal.timeout(45000)})));responses.forEach(r=>assert(r.ok,'PDF 의존 파일 접근 실패 '+r.status));
 const [pdfSource,fontkitSource,fontBytes]=await Promise.all([responses[0].text(),responses[1].text(),responses[2].arrayBuffer()]);
 const {api,context:runtime}=setup({Uint8Array,ArrayBuffer});vm.runInContext(pdfSource,runtime);vm.runInContext(fontkitSource,runtime);
 const c={...api.courses[0],title:'교육안내문 한글 검증',description:'한글 과정 소개',objectives:'현업에서 활용할 수 있다.',curriculum:'1일차\n개념 학습\n2일차\n실무 적용',materials:'노트북 지참',notices:'필수 계정 사전 준비'};
 const result=await api.buildCourseGuidePdf(c,null,{PDFLib:runtime.PDFLib,fontkit:runtime.fontkit,fontBytes});
 assert(result.drawn.filter(d=>d.page===2).every(d=>!['사전 준비','기타 안내','교육 문의'].includes(d.text)));assert(result.drawn.some(d=>d.page===1&&d.text==='사전 준비'));assert(result.drawn.some(d=>d.text==='(세부내용은 2페이지 참조)'));assert(result.bytes.length>1000);const parsed=await runtime.PDFLib.PDFDocument.load(result.bytes);assert.equal(parsed.getPageCount(),2);assert.equal(parsed.getTitle(),c.title+' 교육안내문');
 for(const p of parsed.getPages()){assert(Math.abs(p.getWidth()-595.28)<.1);assert(Math.abs(p.getHeight()-841.89)<.1)}
 const printSource=await runtime.PDFLib.PDFDocument.create();for(const [w,h,rotation]of [[1000,550,0],[600,1000,0],[600,1000,90],[600,1000,180],[1000,600,270]]){const page=printSource.addPage();page.setSize(w,h);page.setRotation(runtime.PDFLib.degrees(rotation));page.drawRectangle({x:1,y:1,width:w-2,height:h-2,borderWidth:2,borderColor:runtime.PDFLib.rgb(1,0,0)});page.drawText('RIGHT EDGE',{x:w-100,y:h/2,size:12})}const printData='data:application/pdf;base64,'+Buffer.from(await printSource.save()).toString('base64');const fitted=await api.fitCurriculumPrintPdf(printData,'',runtime.PDFLib);assert.equal(fitted.placements.length,5);for(const p of fitted.placements){assert(p.left>=28.3);assert(p.bottom>=28.3);assert(p.left+p.width<=p.pageWidth-28.3);assert(p.bottom+p.height<=p.pageHeight-28.3)}const fittedDoc=await runtime.PDFLib.PDFDocument.load(fitted.bytes);assert.equal(fittedDoc.getPageCount(),5);
 const contactCourse={...c,target:'검증 교육대상',educationContacts:[{company:'검증회사',name:'검증담당',position:'차장',phone:'02-1234-5678'}]};const contactPdf=await api.buildCourseGuidePdf(contactCourse,null,{PDFLib:runtime.PDFLib,fontkit:runtime.fontkit,fontBytes});const venueLabel=contactPdf.drawn.find(d=>d.text==='교육장소'),targetLabel=contactPdf.drawn.find(d=>d.text==='교육대상'),timeLabel=contactPdf.drawn.find(d=>d.text==='교육시간'),contactLabel=contactPdf.drawn.find(d=>d.text==='교육담당');assert(venueLabel&&targetLabel&&timeLabel&&contactLabel);assert.equal(targetLabel.y,venueLabel.y);assert(targetLabel.x>venueLabel.x);assert(targetLabel.y<timeLabel.y);assert(contactPdf.drawn.some(d=>d.text.includes('검증담당 차장')));


 const original=await runtime.PDFLib.PDFDocument.create();const page1=original.addPage();page1.setSize(500,300);page1.drawText('ORIGINAL CURRICULUM ONE',{x:25,y:180,size:22});const page2=original.addPage();page2.setSize(500,300);page2.drawText('ORIGINAL CURRICULUM TWO',{x:25,y:180,size:22});const originalData='data:application/pdf;base64,'+Buffer.from(await original.save()).toString('base64');const attached=await api.buildCourseGuidePdf({...c,curriculumArtwork:originalData,curriculum:'DO NOT DUPLICATE TEXT'},null,{PDFLib:runtime.PDFLib,fontkit:runtime.fontkit,fontBytes});assert.equal(attached.pageCount,3);assert(attached.drawn.some(d=>d.text.includes('DO NOT DUPLICATE TEXT')));const selected=await api.buildCourseGuidePdf({...c,curriculumArtwork:originalData,curriculumArtworkPages:'2'},null,{PDFLib:runtime.PDFLib,fontkit:runtime.fontkit,fontBytes});assert.equal(selected.pageCount,2);

 const snippets=await runtime.PDFLib.PDFDocument.create();for(let i=0;i<3;i++){const p=snippets.addPage();p.setSize(500,300);p.drawText('CURRICULUM SECTION '+(i+1),{x:25,y:180,size:22});p.drawRectangle({x:25,y:170,width:450,height:1})}const snippetData='data:application/pdf;base64,'+Buffer.from(await snippets.save()).toString('base64');const packed=await api.buildCourseGuidePdf({...c,curriculumArtwork:snippetData,curriculum:'Written curriculum stays above all three attachments.'},null,{PDFLib:runtime.PDFLib,fontkit:runtime.fontkit,fontBytes,artworkBounds:[0,1,2].map(()=>({left:15,bottom:160,right:485,top:210}))});assert.equal(packed.pageCount,2);const placements=packed.drawn.filter(x=>x.attachment);assert.equal(placements.length,3);assert(placements.every(x=>x.page===2&&x.bottom>=65&&x.left>=38&&x.left+x.width<=558));for(let i=1;i<placements.length;i++)assert(placements[i].bottom+placements[i].height<placements[i-1].bottom);
 const fullPages=await api.buildCourseGuidePdf({...c,curriculumArtwork:printData,curriculum:''},null,{PDFLib:runtime.PDFLib,fontkit:runtime.fontkit,fontBytes});assert.equal(fullPages.drawn.filter(x=>x.attachment).length,5);for(const x of fullPages.drawn.filter(x=>x.attachment)){assert(x.bottom>=64.99);assert(x.left+x.width<=558)}
 const qrResponse=await fetch('https://cdn.jsdelivr.net/npm/qrcode-generator@1.4.4/qrcode.js');assert(qrResponse.ok);vm.runInContext(await qrResponse.text(),runtime);runtime.window.qrcode=runtime.qrcode;const mapped=await api.buildCourseGuidePdf({...c,mapData:'data:image/png;base64,YQ=='},null,{PDFLib:runtime.PDFLib,fontkit:runtime.fontkit,fontBytes});assert(mapped.drawn.some(d=>d.text==='약도 보기'&&d.page===1));assert(!mapped.drawn.some(d=>d.text==='담당강사명'));
 for(const theme of ['required','job','ai']){const themed=await api.buildCourseGuidePdf({...c,guide:{theme},title:'2026년 하반기 소비자보호팀 직무맞춤과정'},{name:'검증강사',company:'교육연구소',position:'대표',specialty:'고객상담 및 리더십',education:'검증대학 석사',career:'기업교육 강의 경력\n조직문화 컨설팅',history:'PDF에 넣지 않을 강의분야',books:'검증 저서',activities:'교육 연구 활동'}, {PDFLib:runtime.PDFLib,fontkit:runtime.fontkit,fontBytes});assert.equal(themed.pageCount,2);assert(themed.drawn.some(d=>d.page===1&&d.text==='검증강사'));const role=themed.drawn.find(d=>d.text==='담당강사'),name=themed.drawn.find(d=>d.text==='검증강사');assert(role&&role.page===name.page&&role.y>name.y);for(const label of ['현소속','학력','경력','저서','주요활동'])assert(themed.drawn.some(d=>d.text.startsWith(label+' · ')));assert(!themed.drawn.some(d=>d.text.includes('PDF에 넣지 않을 강의분야')));assert(!themed.drawn.some(d=>d.text.startsWith('전문분야 · ')));}
});



test('약도는 안전한 이미지·PDF만 지원하고 과정별 공개주소로 연결',async()=>{const {api,node}=setup();assert(api.validMapData('data:image/png;base64,YQ=='));assert(api.validMapData('data:application/pdf;base64,YQ=='));assert(!api.validMapData('data:text/html;base64,YQ=='));assert(!api.validMapData('javascript:alert(1)'));assert.equal(api.courseMapUrl({id:'course 1'}),'https://taekwang-learning-center.onrender.com/?map=course%201');await assert.rejects(api.readMapFile({type:'image/svg+xml',size:10}));await assert.rejects(api.readMapFile({type:'image/png',size:3*1024*1024}));api.editCourse('c1');for(const name of ['mapData','mapName'])assert(node('modalRoot').innerHTML.includes('name="'+name+'"'));assert(node('modalRoot').innerHTML.includes('course-edit-modal'));assert(node('modalRoot').innerHTML.includes('Ctrl+V'));api.courses[0].mapData='data:image/png;base64,YQ==';api.showCourseDetail('c1');assert(node('modalRoot').innerHTML.includes('id="detailCourseMap"'))});

test('세션 만료 시 작성 데이터와 revision을 유지하고 재인증 후 한 번 재저장',async()=>{let reauth=0;const bodies=[];const {api}=setup({fetch:async(url,options)=>{bodies.push(JSON.parse(options.body));if(bodies.length===1)return {ok:false,status:401,json:async()=>({error:'관리자 로그인 후 이용하세요.'})};return {ok:true,json:async()=>({revision:2,...bodies[1].state})}}});api.configureSaveTest('google-sheets',async()=>{reauth++;return true});api.courses[0].title='저장 중 작성한 내용';await api.savePortalState();assert.equal(reauth,1);assert.equal(bodies.length,2);assert.deepEqual(bodies[0],bodies[1]);assert.equal(bodies[1].state.courses[0].title,'저장 중 작성한 내용')});
