function prepareApplication(api,node){api.configureApplyTest();const c=api.courses[0];c.date='2099-01-01';c.endDate=c.date;c.capacity=500;c.closed=false;for(const [id,value]of Object.entries({applyCourse:c.id,phone:'01012345678',employeeId:'APPLY-TEST',employee:'신청자',company:'테스트회사',department:'교육팀',email:'test@example.com',motivation:'교육 신청'}))node(id).value=value;node('applyForm').reset=()=>{};return c}
test('교육신청은 즉시 진행 표시·중복 클릭 차단 후 전체 목록 갱신을 기다리지 않고 완료',async()=>{let accept,refresh;const requests=[];const {api,node}=setup({setInterval:()=>1,clearInterval(){},alert:m=>assert.fail(m),fetch:async url=>{requests.push(url);if(url.endsWith('/apply')){await new Promise(r=>accept=r);return {ok:true,json:async()=>({applicationId:'saved'})}}await new Promise(r=>refresh=r);return {ok:true,json:async()=>({revision:2,courses:[],instructors:[],counts:{}})}}});prepareApplication(api,node);const pending=node('applyForm').onsubmit({preventDefault(){}});assert.equal(node('applySubmit').disabled,true);assert.equal(node('applyReset').disabled,true);assert.equal(node('applyProgress').hidden,false);assert(node('applyProgressText').textContent.includes('저장'));await node('applyForm').onsubmit({preventDefault(){}});assert.equal(requests.length,1);accept();await pending;assert.deepEqual(requests,['/api/data/apply','/api/data/public']);assert.equal(node('applySubmit').disabled,false);assert.equal(node('applyProgress').hidden,true);assert(node('toast').textContent.includes('접수되었습니다'));refresh();await Promise.resolve()});
test('신청 저장 실패는 입력 유지·버튼 복구하며 같은 요청 ID로 재시도',async()=>{const bodies=[];const {api,node}=setup({setInterval:()=>1,clearInterval(){},alert(){},fetch:async(_url,options)=>{bodies.push(JSON.parse(options.body));return {ok:false,status:503,json:async()=>({error:'일시적인 저장소 오류'})}}});prepareApplication(api,node);await node('applyForm').onsubmit({preventDefault(){}});assert.equal(node('employee').value,'신청자');assert.equal(node('applySubmit').disabled,false);assert(node('applyProgressText').textContent.includes('입력 내용은 유지'));await node('applyForm').onsubmit({preventDefault(){}});assert.equal(bodies[0].application.id,bodies[1].application.id)});


test('상세 제목에 출력 버튼·강사 옆 프로필·모집현황 아래 대상 배치 및 커리큘럼 번호 제거',()=>{const {api,node}=setup();const c=api.courses[0];c.target='검증 교육대상';c.curriculum='검증 커리큘럼 본문';api.showCourseDetail(c.id);const out=node('modalRoot').innerHTML;assert(out.indexOf('id="printCourseOutline"')<out.indexOf('class="course-hero"'));assert(out.includes('교육 안내문 출력'));assert(out.includes('🖨️'));assert(out.indexOf('id="viewCourseInstructor"')>out.indexOf('<small>담당강사</small>'));assert(out.indexOf('id="viewCourseInstructor"')<out.indexOf('id="courseSection-audience"'));assert(out.indexOf('id="courseSection-audience"')>out.indexOf('<small>모집현황</small>'));assert.equal((out.match(/id="courseSection-audience"/g)||[]).length,1);assert(out.includes('검증 교육대상'));assert(out.includes('course-curriculum-box'));assert(!out.includes('module-number'));assert(!out.includes('<h4>교육내용</h4>'));assert(!out.includes('course-detail-actions'))});


test('커리큘럼 전체 화면 전환과 복귀 및 미지원 브라우저 확대 대체',async()=>{const {api,node,context}=setup();const classes=new Set();let requested=0,exited=0;const layer={classList:{contains:x=>classes.has(x),add:x=>classes.add(x),remove:x=>classes.delete(x)},requestFullscreen:async()=>{requested++;context.document.fullscreenElement=layer}};context.document.exitFullscreen=async()=>{exited++;context.document.fullscreenElement=null};node('fullscreenCurriculumView').setAttribute=()=>{};api.attachCurriculumFullscreen(layer);await node('fullscreenCurriculumView').onclick();assert.equal(requested,1);assert(classes.has('curriculum-expanded'));assert(node('fullscreenCurriculumView').textContent.includes('원래 크기'));await node('fullscreenCurriculumView').onclick();assert.equal(exited,1);assert(!classes.has('curriculum-expanded'));layer.requestFullscreen=async()=>{throw Error('지원 안 함')};await node('fullscreenCurriculumView').onclick();assert(classes.has('curriculum-expanded'));await node('fullscreenCurriculumView').onclick();assert(!classes.has('curriculum-expanded'))});



