test('교육담당 1명 등록·상세·문의 문구·PDF 모델 연동 및 누락 시 기본 담당 유지',()=>{const {api,node}=setup();const c=api.courses[0];c.educationContacts=[{company:'테스트생명',name:'홍길동',position:'차장',phone:'02-1234-5678'},{company:'테스트화재',name:'김교육',position:'과장',phone:'010-1234-5678'},{company:'제외회사',name:'제외',position:'대리',phone:'02-0000-0000'}];assert.equal(api.courseEducationContacts(c).length,1);api.showCourseDetail(c.id);const out=node('modalRoot').innerHTML;assert(!out.includes('course-section-nav'));assert(out.includes('테스트생명'));assert(out.includes('홍길동 차장'));assert(out.includes('02-1234-5678'));assert(!out.includes('제외회사'));assert(api.courseGuideModel(c,null).coordinators.includes('홍길동 차장'));assert(api.courseGuideModel(c,null).contact.includes('02-1234-5678'));api.editCourse(c.id);for(const field of ['company','name','position','phone'])for(const index of [0])assert(node('modalRoot').innerHTML.includes('name="educationContact'+index+field+'"'));assert.equal(api.courseEducationContacts({}).length,1);assert.equal(api.courseEducationContacts({educationContacts:[]}).length,0);const d={get:key=>key==='educationContact0name'?'입력자':''};assert.equal(api.readEducationContacts(d)[0].name,'입력자')});


