test('과정 등록은 기본 입력 한 줄·첨부 위치·디자인만 유지하고 오래된 요약값 무시',()=>{const {api,node}=setup();api.editCourse('c1');const out=node('modalRoot').innerHTML;assert(!out.includes('자료로 교육내용 채우기'));assert(!out.includes('name="guideIntro"'));assert(!out.includes('name="guideGoals"'));assert(!out.includes('name="guideCurriculum"'));assert(out.includes('name="guideTheme"'));assert(out.indexOf('세부내용 첨부하기')>out.indexOf('name="curriculum"'));assert(out.indexOf('세부내용 첨부하기')<out.indexOf('name="materials"'));assert(out.includes('PDF에서 사용할 페이지'));assert(out.includes('캡처 이미지 붙여넣기'));assert(out.includes('rows="1"'));const c={...api.courses[0],description:'과정설명 원문 전체 '+('상세 내용 '.repeat(90)),objectives:'학습목표 원문 전체 '+('달성 목표 '.repeat(80)),curriculum:'세부내용 원문 전체',notices:'안내사항 원문 전체',guide:{intro:'이전 요약',goals:'이전 목표 요약',curriculum:'이전 커리큘럼 요약'}};const model=api.courseGuideModel(c,null);assert.equal(model.intro,c.description);assert.equal(model.goals,c.objectives);assert.equal(model.curriculum,c.curriculum);assert.equal(model.notices,c.notices);assert(!model.intro.includes('이전 요약'))});

test('승인 변경 요청에는 약도와 첨부파일을 다시 전송하지 않고 변경 필드만 포함',()=>{const {api}=setup();const before={courses:[{id:'c1',mapData:'large-image',curriculumArtwork:'large-pdf'}],instructors:[],apps:[{id:'a1',status:'신청완료',phone:'01012345678'}]},after=JSON.parse(JSON.stringify(before));after.apps[0].status='승인';const changes=JSON.parse(JSON.stringify(api.storageChanges(before,after)));assert.deepEqual(changes,[{collection:'apps',id:'a1',before:{status:'신청완료'},after:{status:'승인'}}]);assert(JSON.stringify(changes).length<200)});
test('저장 진행 표시는 즉시 표시되고 중복 저장 차단 후 버튼과 표시 복구',async()=>{let finish;const buttons=[{disabled:false,textContent:'승인 중…'}];let shown=false,removed=false;const progress={setAttribute(){},remove(){removed=true}};const {api,context}=setup();await Promise.resolve();api.configureSaveTest('google-sheets',()=>true);context.document.querySelectorAll=()=>buttons;context.document.createElement=()=>progress;context.document.body={appendChild(){shown=true}};context.fetch=async()=>{await new Promise(resolve=>finish=resolve);return new Response(JSON.stringify({revision:2}))};const pending=api.safeSave();assert.equal(shown,true);assert.equal(buttons[0].disabled,true);assert.equal(await api.safeSave(),false);await new Promise(resolve=>setTimeout(resolve,0));finish();assert.equal(await pending,true);assert.equal(buttons[0].disabled,false);assert.equal(removed,true)});

test('지난교육은 시작일이 아닌 종료일과 한국 날짜를 기준으로 구분',()=>{const {api}=setup();assert.equal(api.isPastCourse({date:'2026-11-01',endDate:'2026-11-02'},'2026-11-02'),false);assert.equal(api.isPastCourse({date:'2026-11-01',endDate:'2026-11-02'},'2026-11-03'),true);assert.equal(api.isPastCourse({date:'2026-11-01'},'2026-11-02'),true);assert.equal(api.isPastCourse(undefined,'2026-11-02'),false)});
test('종료 과정은 현재 목록·승인관리에서 분리되고 원본·첨부·신청자는 보존',()=>{const {api,node}=setup();const c=api.courses[0],app=api.apps.find(a=>a.courseId===c.id);c.date='2000-01-01';c.endDate='2000-01-02';c.title='보관 과정 테스트';c.mapData='preserved-map';c.curriculumArtwork='preserved-curriculum';const before=JSON.stringify(api.getData());api.render();assert(!node('courseGrid').innerHTML.includes(c.title));assert(!node('adminCourseRows').innerHTML.includes(c.title));assert(node('archiveCourseRows').innerHTML.includes(c.title));assert(node('archiveCourseRows').innerHTML.includes('신청자 보기'));assert(node('archiveCourseRows').innerHTML.includes('명단 CSV'));assert(!node('adminApplicationRows').innerHTML.includes(c.title));assert.equal(JSON.stringify(api.getData()),before);api.setAdminState(true);api.showArchivedApplications(c.id);assert.equal(node('statusCourseFilter').value,c.id);assert(node('statusRows').innerHTML.includes(app.name));assert.equal(api.filteredSmsRows().length,api.apps.filter(a=>a.courseId===c.id).length);c.date='2099-01-01';c.endDate='2099-01-02';api.render();assert(!node('archiveCourseRows').innerHTML.includes(c.title));assert(node('adminCourseRows').innerHTML.includes(c.title))});
test('지난교육 검색·연도 필터와 관리자 내부 탭 연결',()=>{const {api,node}=setup();const c=api.courses[0];c.date='2000-01-01';c.endDate='2000-01-02';c.title='아카이브 검색 대상';api.renderArchive();assert(node('archiveYear').innerHTML.includes('2000년'));node('archiveSearch').value='없는 검색어';api.renderArchive();assert(node('archiveCourseRows').innerHTML.includes('검색 결과가 없습니다'));node('archiveSearch').value='검색 대상';node('archiveYear').value='2000';api.renderArchive();assert(node('archiveCourseRows').innerHTML.includes(c.title));let hidden;node('archiveView').classList.toggle=(_,value)=>hidden=value;api.setAdminState(true);api.nav('archive');assert.equal(hidden,false);api.nav('admin');assert.equal(hidden,false);assert(html.includes('data-admin-tab="archive"'))});

test('첨부 여백 분석은 흰색·투명 여백을 제외하고 옅은 선과 내용은 유지',()=>{const {api}=setup(),w=60,h=60,pixels=new Uint8ClampedArray(w*h*4).fill(255);for(let y=20;y<30;y++)for(let x=25;x<35;x++){const i=(y*w+x)*4;pixels[i]=pixels[i+1]=pixels[i+2]=230}const b=api.curriculumInkBounds(pixels,w,h);assert.deepEqual(JSON.parse(JSON.stringify(b)),{left:17,top:12,right:43,bottom:38});assert.equal(api.curriculumInkBounds(new Uint8ClampedArray(w*h*4),w,h),null);assert.equal(api.curriculumInkBounds(new Uint8ClampedArray(w*h*4).fill(255),w,h),null)});

test('숫자 4·6자리 관리자 비밀번호 허용·5자리 거부 및 강사 사진 480px 사전 최적화',async()=>{const {api,node,context}=setup();await api.adminAction('setup',{password:'4826'});await api.adminAction('login',{password:'4826'});api.setAdminState(true);await api.adminAction('change',{currentPassword:'4826',password:'482631'});await assert.rejects(api.adminAction('change',{currentPassword:'482631',password:'12345'}),/숫자 4자리 또는 6자리/);let quality,canvas;context.Image=class{constructor(){this.width=1200;this.height=1600}set src(value){this.onload()}};context.document.createElement=()=>canvas={getContext:()=>({fillRect(){},drawImage(){}}),toDataURL:(_type,q)=>{quality=q;return 'data:image/jpeg;base64,small'}};const result=await api.compactStoredImage('data:image/png;base64,'+'A'.repeat(100000),480,.82,80000);assert.equal(canvas.height,480);assert.equal(canvas.width,360);assert.equal(quality,.82);assert.equal(result,'data:image/jpeg;base64,small');api.editCourse();assert(node('modalRoot').innerHTML.includes('교육내용(커리큘러)'))});

test('강사사진은 우측 미리보기·후보 영역에 배치하고 PDF 파일을 직접 선택 가능',()=>{const {api,node}=setup();api.editInstructor();const markup=node('modalRoot').innerHTML;assert(markup.includes('instructor-photo-layout'));assert(markup.includes('instructor-photo-side'));assert(markup.includes('사진이 여기에 표시됩니다'));assert(markup.includes('accept="application/pdf,.pdf,image/png,image/jpeg,image/webp"'));assert(!html.includes('data-cap="screen"'));assert(!html.includes('getDisplayMedia'));assert(!html.includes('열린 창 캡처를 이용하세요'))});
test('PDF 사진 추출은 원본 RGB·회색조 사진 후보를 고르고 통스캔·가로 로고는 제외',async()=>{const {api,context}=setup();const OPS={paintImageXObject:1,paintJpegXObject:2,paintInlineImageXObject:3};context.pdfjsLib={OPS};let count=0;context.document.createElement=()=>({getContext:()=>({createImageData:(w,h)=>({data:new Uint8ClampedArray(w*h*4)}),putImageData(){},drawImage(){},fillRect(){}}),toDataURL:()=> 'data:image/jpeg;base64,candidate'+(++count)});const image=(w,h,channels=3)=>({width:w,height:h,data:new Uint8Array(w*h*channels)}),images={portrait:image(180,240),gray:image(120,160,1),logo:image(500,90)};const page={getOperatorList:async()=>({fnArray:[1,1,1],argsArray:[['portrait'],['gray'],['logo']]}),objs:{get:key=>images[key]},getTextContent:async()=>({items:Array.from({length:15},()=>({str:'이력'}))}),getViewport:()=>({width:595,height:842})};const found=await api.pdfPhotoCandidates({numPages:1,getPage:async()=>page});assert.equal(found.length,2);assert.equal(found[0].width,180);assert.equal(found[1].width,120);assert(found.every(x=>x.url.startsWith('data:image/jpeg')));const scan={...page,getOperatorList:async()=>({fnArray:[1],argsArray:[['scan']]}),objs:{get:()=>image(595,842)},getTextContent:async()=>({items:[]})};assert.equal((await api.pdfPhotoCandidates({numPages:1,getPage:async()=>scan})).length,0)});
test('사진 후보 선택은 우측 미리보기와 실제 저장 대상에 같은 원본을 적용',()=>{const {api,node,context}=setup();api.editInstructor();const form=node('instructorForm');form.dataset={};form.elements.photo.value='previous.pdf';const buttons=[];context.document.createElement=tag=>({tag,setAttribute(){},append(){}});node('instructorPhotoCandidates').append=b=>buttons.push(b);api.showInstructorPhotoCandidates([{page:1,url:'data:image/jpeg;base64,one'},{page:2,url:'data:image/jpeg;base64,two'}],form);assert.equal(form.dataset.pdfPhoto,'data:image/jpeg;base64,one');assert.equal(node('pdfPhotoPreview').src,form.dataset.pdfPhoto);assert.equal(node('instructorPhotoCandidates').hidden,false);buttons[1].onclick();assert.equal(form.dataset.pdfPhoto,'data:image/jpeg;base64,two');assert.equal(node('pdfPhotoPreview').src,form.dataset.pdfPhoto);assert.equal(form.elements.photo.value,'')});

test('강제 지난교육 이동은 신청 마감과 분류만 바꾸고 신청자·첨부자료 보존 및 복원',async()=>{const {api,node}=setup({confirm:()=>true});await Promise.resolve();api.configureSaveTest('local',()=>true);const c=api.courses[0];c.date='2099-01-01';c.endDate='2099-01-02';c.closed=false;c.mapData='saved-map';c.curriculumArtwork='saved-curriculum';const apps=JSON.stringify(api.apps);assert.equal(await api.setCourseArchived(c.id,true),true);let moved=api.getData().courses.find(x=>x.id===c.id);assert.equal(moved.archived,true);assert.equal(moved.closed,true);assert.equal(moved.mapData,c.mapData);assert.equal(moved.curriculumArtwork,c.curriculumArtwork);assert.equal(api.isPastCourse(moved),true);assert.equal(JSON.stringify(api.getData().apps),apps);assert(node('archiveCourseRows').innerHTML.includes('운영 목록 복원'));assert(!node('applyCourse').innerHTML.includes('value="'+c.id+'"'));assert.equal(await api.setCourseArchived(c.id,false),true);moved=api.getData().courses.find(x=>x.id===c.id);assert.equal(api.isPastCourse(moved),false);assert.equal(moved.closed,true);assert(node('adminCourseRows').innerHTML.includes('지난교육으로 이동'))});
test('강제 보관은 관리자만 가능하고 취소·저장 실패는 기존 데이터 유지',async()=>{let confirmation=false;const {api,context}=setup({confirm:()=>confirmation,alert:()=>{}});await Promise.resolve();const c=api.courses[0];c.date=c.endDate='2099-01-01';const before=JSON.stringify(api.getData());assert.equal(await api.setCourseArchived(c.id,true),false);api.configureSaveTest('local',()=>true);assert.equal(await api.setCourseArchived(c.id,true),false);assert.equal(JSON.stringify(api.getData()),before);confirmation=true;api.configureSaveTest('google-sheets',()=>true);context.fetch=async()=>new Response(JSON.stringify({error:'mock fail'}),{status:503});assert.equal(await api.setCourseArchived(c.id,true),false);assert.equal(JSON.stringify(api.getData()),before)});

test('신청 리셋의 최종 경고를 취소하면 신청·과정·강사 모두 그대로 유지',async()=>{let count=0;const {api}=setup({confirm:()=>++count===1});api.setAdminState(true);const before=JSON.stringify(api.getData());assert.equal(await api.resetPortalData(),false);assert.equal(count,2);assert.equal(JSON.stringify(api.getData()),before)});
test('모집 마감 과정에 신청자가 있어도 2회 확인 후 연결 내역만 함께 삭제',async()=>{const messages=[];const {api,node}=setup({confirm:message=>{messages.push(message);return true}});await Promise.resolve();api.configureSaveTest('local',()=>true);const c=api.courses[0];c.closed=true;const other=api.getData().apps.filter(a=>a.courseId!==c.id),instructors=JSON.stringify(api.instructors);assert.equal(await api.deleteCourseWithApplications(c.id),true);assert.equal(messages.length,2);assert(messages[0].includes('신청내역'));assert(!api.getData().courses.some(x=>x.id===c.id));assert.deepEqual(JSON.parse(JSON.stringify(api.getData().apps)),JSON.parse(JSON.stringify(other)));assert.equal(JSON.stringify(api.getData().instructors),instructors)});

test('선택 일괄 취소는 표시 중인 선택·유효 신청만 바꾸고 기록과 다른 과정 보존',async()=>{const {api,node}=setup({confirm:()=>true});await Promise.resolve();api.configureSaveTest('local',()=>true);const rows=api.apps;rows[0].status='신청완료';rows[1].status='승인';rows[2].status='반려';const visibleId=rows[0].courseId;node('statusCourseFilter').value=visibleId;api.smsSelection.add(rows[0].id);api.smsSelection.add(rows[2].id);const before=JSON.parse(JSON.stringify(api.getData()));assert.equal(await api.cancelApplications('selected'),true);const after=api.getData();assert.equal(after.apps.length,before.apps.length);assert.equal(after.apps.find(a=>a.id===rows[0].id).status,'취소');assert.equal(after.apps.find(a=>a.id===rows[1].id).status,'승인');assert.equal(after.apps.find(a=>a.id===rows[2].id).status,'반려');assert.equal(JSON.stringify(after.courses),JSON.stringify(before.courses));assert.equal(JSON.stringify(after.instructors),JSON.stringify(before.instructors))});
test('현재 목록 일괄 취소는 검색·상태 조건을 지키고 취소·반려는 유지',async()=>{let asked=0;const {api,node}=setup({confirm:()=>{asked++;return true}});await Promise.resolve();api.configureSaveTest('local',()=>true);api.apps[0].status='신청완료';api.apps[1].status='승인';api.apps[2].status='취소';node('statusFilter').value='승인';assert.equal(await api.cancelApplications('all'),true);assert.equal(asked,1);assert.equal(api.getData().apps[0].status,'신청완료');assert.equal(api.getData().apps[1].status,'취소');assert.equal(api.getData().apps[2].status,'취소')});
test('일괄 취소는 관리자만 가능하며 확인 취소·저장 실패 시 기록 원복',async()=>{let confirmed=false;const {api,context}=setup({confirm:()=>confirmed,alert:()=>{}});await Promise.resolve();api.smsSelection.add(api.apps[0].id);assert.equal(await api.cancelApplications(),false);api.configureSaveTest('local',()=>true);const before=JSON.stringify(api.getData());assert.equal(await api.cancelApplications(),false);assert.equal(JSON.stringify(api.getData()),before);confirmed=true;api.configureSaveTest('google-sheets',()=>true);context.fetch=async()=>new Response(JSON.stringify({error:'mock failure'}),{status:503});assert.equal(await api.cancelApplications(),false);assert.equal(JSON.stringify(api.getData()),before)});
test('모집 마감 과정의 실제 삭제 버튼은 신청자 차단 없이 새 삭제 처리에 연결',async()=>{const {api,context}=setup({confirm:()=>true,alert:()=>{throw Error('잘못된 구형 삭제 경고')}});await Promise.resolve();api.configureSaveTest('local',()=>true);const c=api.courses[0];c.closed=true;const button={dataset:{delete:c.id}};context.document.querySelectorAll=selector=>selector==='[data-delete]'?[button]:[];api.renderAdmin();assert.equal(typeof button.onclick,'function');assert.equal(await button.onclick(),true);assert(!api.getData().courses.some(x=>x.id===c.id));assert(!api.getData().apps.some(x=>x.courseId===c.id));assert(!html.includes('신청 내역이 있는 과정은 삭제할 수 없습니다.'))});
